import { forbidden } from 'next/navigation';
import { getSession } from '../lib/auth';

export default async function AdminPage() {
  const session = await getSession();

  if (!session || session.role !== 'admin') {
    forbidden();
  }

  return (
    <main style={{ padding: '2rem', fontFamily: 'sans-serif', maxWidth: '800px', margin: '0 auto' }}>
      <h1 style={{ borderBottom: '1px solid #ddd', paddingBottom: '1rem' }}>Admin Dashboard</h1>
      <div style={{ marginTop: '2rem' }}>
        <p>Welcome back, <strong>{session.name}</strong>!</p>
        <p>You have full access to the system settings and user management.</p>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: '1rem', marginTop: '2rem' }}>
          <div style={{ padding: '1rem', border: '1px solid #ddd', borderRadius: '8px', backgroundColor: '#f9f9f9' }}>
            <h3>Users</h3>
            <p style={{ color: '#666' }}>Manage user accounts</p>
          </div>
          <div style={{ padding: '1rem', border: '1px solid #ddd', borderRadius: '8px', backgroundColor: '#f9f9f9' }}>
            <h3>Settings</h3>
            <p style={{ color: '#666' }}>System configuration</p>
          </div>
          <div style={{ padding: '1rem', border: '1px solid #ddd', borderRadius: '8px', backgroundColor: '#f9f9f9' }}>
            <h3>Logs</h3>
            <p style={{ color: '#666' }}>View system activity</p>
          </div>
        </div>
      </div>
    </main>
  );
}

