import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import AdminPage from './page';
import * as auth from '../lib/auth';
import * as navigation from 'next/navigation';

// Mock dependencies
vi.mock('../lib/auth', () => ({
  getSession: vi.fn(),
}));

vi.mock('next/navigation', () => ({
  forbidden: vi.fn(),
}));

describe('AdminPage', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('renders dashboard for admin users', async () => {
    // Mock getSession to return an admin user
    vi.mocked(auth.getSession).mockResolvedValue({
      userId: '1',
      role: 'admin',
      name: 'Admin User',
    });

    const Page = await AdminPage();

    // Since page is an async server component, we can just call it and check the result or check side effects
    // However, react-testing-library render() expects a React element.
    // For async server components in tests, we can await the result and inspect it if it's JSX, 
    // or just check the side effects (forbidden call).

    // In this case, AdminPage returns a JSX element.
    expect(Page).toBeDefined();
    expect(vi.mocked(navigation.forbidden)).not.toHaveBeenCalled();

    // To properly test the render output of an async component without a full Next.js environment,
    // we can inspect the returned object, but checking forbidden() is the key logic here.
  });

  it('calls forbidden() for non-admin users', async () => {
    // Mock getSession to return a regular user
    vi.mocked(auth.getSession).mockResolvedValue({
      userId: '2',
      role: 'user',
      name: 'Regular User',
    });

    try {
      await AdminPage();
    } catch (e) {
      // forbidden() might throw, but we mocked it to a simple fn
    }

    expect(vi.mocked(navigation.forbidden)).toHaveBeenCalled();
  });

  it('calls forbidden() for unauthenticated users', async () => {
    // Mock getSession to return null
    vi.mocked(auth.getSession).mockResolvedValue(null);

    try {
      await AdminPage();
    } catch (e) {}

    expect(vi.mocked(navigation.forbidden)).toHaveBeenCalled();
  });
});

